    'card-payment':id=>{if(ensureAccount())transactionForm(null,account(id));},categories:categoriesDialog,'new-category':()=>categoryForm(),'edit-category':id=>categoryForm(category(id)),rates:ratesDialog,tools:toolsDialog,
    'base-currency':()=>dialog('Ana para birimi','settings',select('baseCurrency','Para birimi',view.currencies.map(id=>({id,name:id})),view.baseCurrency)+'<p class="budget-muted">İşlem veya bütçe kaydından sonra değiştirilemez; geçmiş tutarların anlamı korunur.</p>'),
    'fund-goal':id=>{const g=view.goals.find(g=>g.id===id);dialog('Hedefe para ayır','fund',field('amount','Tutar · '+g.currency,'','text','required inputmode="decimal"')+check('withdraw','Ayrılan parayı geri al')+`<input type="hidden" name="goalId" value="${esc(id)}"><p class="budget-muted">Hesap bakiyesi değişmez, ayrılan miktar rezerv olarak gösterilir.</p>`);},
    'pay-plan':id=>{const [planId,occurrence]=id.split('|'),p=view.plans.find(p=>p.id===planId);dialog(p.type==='income'?'Gelir alındı':'Ödemeyi kaydet','pay',`<input type="hidden" name="planId" value="${esc(planId)}"><input type="hidden" name="occurrence" value="${esc(occurrence)}">${field('date','Gerçekleşme tarihi',view.today,'date','required')}${field('rate','İşlem kuru · 1 birim = '+view.baseCurrency,String(p.rate/1000000),'text','inputmode="decimal"')}${button('skip-plan','Bu tarihi atla',id)}<p class="budget-muted">Bu tarih için yalnız bir kayıt oluşturulur.</p>`);},
    'skip-plan':async id=>{const [planId,occurrence]=id.split('|');await mutate('skip',{planId,occurrence});editor.close();},
    'pause-plan':async id=>{await mutate('pausePlan',{id});editor.close();},
    'delete-budget':async id=>{await mutate('removeBudget',{id});},
    'delete-transaction':async id=>{await mutate('remove',{id});editor.close();message('İşlem silindi. Silinenler bölümünden geri alabilirsin.');},
    'trash':()=>dialog('Silinen işlemler',null,view.deleted.map(d=>`<div class="budget-category-manage"><span>${esc(d.note||'İşlem')}<small>${currency(d.amount,d.currency)}</small></span>${button('undo', 'Geri al',d.id)}</div>`).join('')||'<p>Silinen işlem yok.</p>'),
    undo:async id=>{await mutate('undo',{id});editor.close();message('İşlem geri alındı.');},
    'attach-receipt':async id=>{await call('budget:receiptAdd',id,month);transactionForm(view.transactions.find(t=>t.id===id));render();},
    'open-receipt':id=>call('budget:receiptOpen',id),'remove-receipt':async id=>{const r=view.receipts.find(r=>r.id===id);await call('budget:receiptRemove',id,month);transactionForm(view.transactions.find(t=>t.id===r.transactionId));},
    'csv-export':()=>call('budget:csvExport',month+'-01',lastDay(month)),'csv-template':()=>call('budget:csvExport'),backup:()=>call('budget:backup'),restore:async()=>{const r=await call('budget:restore',month);if(r){editor.close();render();message('Bütçe yedeği yüklendi.');}},
